CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

CREATE TABLE IF NOT EXISTS users (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK (role IN ('farmer','buyer')), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS farmer_profiles (user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, name TEXT NOT NULL, location TEXT, preferred_language TEXT DEFAULT 'en');
CREATE TABLE IF NOT EXISTS buyer_profiles (user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, business_name TEXT NOT NULL, location TEXT, verified BOOLEAN DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS crops (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), name TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS markets (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), name TEXT NOT NULL, city TEXT, state TEXT, latitude DOUBLE PRECISION, longitude DOUBLE PRECISION);
CREATE TABLE IF NOT EXISTS market_prices (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), market_id UUID NOT NULL REFERENCES markets(id) ON DELETE CASCADE, crop_id UUID NOT NULL REFERENCES crops(id), price_min NUMERIC(12,2), price_max NUMERIC(12,2), modal_price NUMERIC(12,2), unit TEXT NOT NULL DEFAULT 'qtl', observed_on DATE NOT NULL);
CREATE TABLE IF NOT EXISTS market_arrivals (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), market_id UUID NOT NULL REFERENCES markets(id) ON DELETE CASCADE, crop_id UUID NOT NULL REFERENCES crops(id), quantity_kg NUMERIC(14,2), observed_on DATE NOT NULL);
CREATE TABLE IF NOT EXISTS farmer_lots (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), farmer_id UUID NOT NULL REFERENCES users(id), crop_id UUID NOT NULL REFERENCES crops(id), quantity_qtl NUMERIC(12,2) NOT NULL, quality TEXT, location TEXT, availability_date DATE, status TEXT NOT NULL DEFAULT 'active');
CREATE TABLE IF NOT EXISTS buyer_requirements (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), buyer_id UUID NOT NULL REFERENCES users(id), crop_id UUID NOT NULL REFERENCES crops(id), quantity_qtl NUMERIC(12,2) NOT NULL, quality TEXT, max_price_per_qtl NUMERIC(12,2), location TEXT, required_date DATE, status TEXT NOT NULL DEFAULT 'active');
CREATE TABLE IF NOT EXISTS buyer_matches (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), lot_id UUID REFERENCES farmer_lots(id), requirement_id UUID REFERENCES buyer_requirements(id), score NUMERIC(6,4), breakdown JSONB, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS offers (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), lot_id UUID REFERENCES farmer_lots(id), buyer_id UUID REFERENCES users(id), offered_price_per_qtl NUMERIC(12,2), status TEXT NOT NULL DEFAULT 'created', created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS deals (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), lot_id UUID REFERENCES farmer_lots(id), buyer_id UUID REFERENCES users(id), status TEXT NOT NULL DEFAULT 'offer_created', quantity_qtl NUMERIC(12,2), agreed_price_per_qtl NUMERIC(12,2), created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS deal_negotiations (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), deal_id UUID NOT NULL REFERENCES deals(id) ON DELETE CASCADE, actor_user_id UUID NOT NULL REFERENCES users(id), message TEXT NOT NULL, offered_price_per_qtl NUMERIC(12,2), created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS payments (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), deal_id UUID NOT NULL REFERENCES deals(id) ON DELETE CASCADE, amount NUMERIC(14,2) NOT NULL, status TEXT NOT NULL DEFAULT 'pending', transaction_reference TEXT, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS transporters (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), name TEXT NOT NULL, verified BOOLEAN DEFAULT FALSE, vehicle_type TEXT, capacity_qtl NUMERIC(12,2), rating NUMERIC(3,2));
CREATE TABLE IF NOT EXISTS transport_requests (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), lot_id UUID REFERENCES farmer_lots(id), source TEXT NOT NULL, destination TEXT NOT NULL, quantity_qtl NUMERIC(12,2), status TEXT NOT NULL DEFAULT 'open');
CREATE TABLE IF NOT EXISTS transport_bids (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), request_id UUID NOT NULL REFERENCES transport_requests(id) ON DELETE CASCADE, transporter_id UUID NOT NULL REFERENCES transporters(id), total_cost NUMERIC(12,2), eta_hours NUMERIC(8,2), risk_score NUMERIC(6,2));
CREATE TABLE IF NOT EXISTS transport_trips (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), request_id UUID NOT NULL REFERENCES transport_requests(id), transporter_id UUID REFERENCES transporters(id), status TEXT NOT NULL DEFAULT 'scheduled');
CREATE TABLE IF NOT EXISTS warehouses (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), name TEXT NOT NULL, location TEXT, capacity_qtl NUMERIC(14,2), available_capacity_qtl NUMERIC(14,2), cost_per_qtl_day NUMERIC(12,2), crop_suitability JSONB);
CREATE TABLE IF NOT EXISTS storage_bookings (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), warehouse_id UUID NOT NULL REFERENCES warehouses(id), lot_id UUID NOT NULL REFERENCES farmer_lots(id), quantity_qtl NUMERIC(12,2), days INT, status TEXT NOT NULL DEFAULT 'reserved');
CREATE TABLE IF NOT EXISTS collective_pools (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), target_destination TEXT, combined_quantity_qtl NUMERIC(12,2), status TEXT NOT NULL DEFAULT 'open');
CREATE TABLE IF NOT EXISTS grievances (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), deal_id UUID REFERENCES deals(id), raised_by UUID REFERENCES users(id), category TEXT NOT NULL, description TEXT NOT NULL, priority TEXT NOT NULL DEFAULT 'medium', status TEXT NOT NULL DEFAULT 'submitted', created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS notifications (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), user_id UUID NOT NULL REFERENCES users(id), type TEXT NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL, read_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS recommendations (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), farmer_id UUID REFERENCES users(id), lot_id UUID REFERENCES farmer_lots(id), action TEXT NOT NULL, net_realization_per_qtl NUMERIC(12,2), confidence NUMERIC(6,4), reasons JSONB, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS simulation_results (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), farmer_id UUID REFERENCES users(id), lot_id UUID REFERENCES farmer_lots(id), scenario JSONB NOT NULL, result JSONB NOT NULL, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS risk_assessments (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), lot_id UUID REFERENCES farmer_lots(id), route JSONB, overall_score NUMERIC(6,2), breakdown JSONB, created_at TIMESTAMPTZ DEFAULT NOW());

CREATE INDEX IF NOT EXISTS idx_market_prices_market_crop_date ON market_prices(market_id,crop_id,observed_on DESC);
CREATE INDEX IF NOT EXISTS idx_lots_farmer_status ON farmer_lots(farmer_id,status);
CREATE INDEX IF NOT EXISTS idx_requirements_buyer_status ON buyer_requirements(buyer_id,status);
CREATE INDEX IF NOT EXISTS idx_deals_lot_buyer ON deals(lot_id,buyer_id);
